{
  "ferramenta": "image_gen integrada",
  "referencias": [
    "assets/art/toy-room/stage2/carry-v2/poses.png",
    "assets/art/toy-room/battle/girl/animation-v2/run-sheet.png"
  ],
  "pranchas": [
    {
      "key": "arena-base",
      "prompt": "Use case: identity-preserve. New production 2D combat sprite atlas. Reference 1 is the APPROVED NEW girl's identity and detailed hand-painted storybook sprite quality. Keep her EXACT face, brown eyes, brown pigtails/pink bows, cream and pink embroidered dress, brown boots, toddler anatomy, short neck. Reference 2 is action/staging reference ONLY, NOT its low-detail pixel style or facial proportions. Same light and proportions in every cell. All full-body sprites face RIGHT, three-quarter side view. Sword is a small wooden toy sword with cream wooden blade and pale cyan crossguard. Genuine alpha-transparent background, NO brown backdrop, NO floor, NO ground shadow, NO text, NO grid, NO sparks or sword arcs. Generous transparent gaps and margins. Head size must be IDENTICAL in crouching/jumping/standing cells; change limb articulation rather than shrinking entire figure. Layout FOUR columns by THREE rows, exactly twelve equal cells. Row 1 four IDLE ready stances holding sword firmly with both hands in front, slight breathing only. Row 2 four clearly distinct sequential RUNNING keyframes with alternate left/right foot contact and passing poses, sword held securely toward right, skirt and hair responding. Row 3 four gradual CROUCH transition poses: first slight knee bend, second medium bend, third low squat, fourth deepest defensive squat. Keep her HEAD SAME SIZE and feet on common baseline in all poses; crouch by bending knees/trunk. Keep sword forward protecting torso. No whole-body scaling between crouch poses."
    },
    {
      "key": "arena-acoes",
      "prompt": "Use case: identity-preserve. New production 2D combat sprite atlas. Reference 1 is the APPROVED NEW girl's identity and detailed hand-painted storybook sprite quality. Keep her EXACT face, brown eyes, brown pigtails/pink bows, cream and pink embroidered dress, brown boots, toddler anatomy, short neck. Reference 2 is action/staging reference ONLY, NOT its low-detail pixel style or facial proportions. Same light and proportions in every cell. All full-body sprites face RIGHT, three-quarter side view. Sword is a small wooden toy sword with cream wooden blade and pale cyan crossguard. Genuine alpha-transparent background, NO brown backdrop, NO floor, NO ground shadow, NO text, NO grid, NO sparks or sword arcs. Generous transparent gaps and margins. Head size must be IDENTICAL in crouching/jumping/standing cells; change limb articulation rather than shrinking entire figure. Layout FOUR columns by THREE rows, twelve equal cells, read left to right then top to bottom. Pose 1 ready stance sword forward. Pose 2 ANTICIPATION, sword drawn back above rear shoulder, weight back. Pose 3 FOLLOW-THROUGH, sword lowered after swing, weight forward. Pose 4 ACTIVE IMPACT, strong horizontal slash fully extended towards RIGHT, sword at chest height, weight forward, BOTH hands gripping handle. Pose 5 RECOVERY, sword returning to ready stance. Pose 6 jump rising knees bent, sword guarded. Pose 7 high jump apex knees tucked, sword guarded. Pose 8 early falling feet extending down, sword guarded. Pose 9 landing anticipation bent knees. Pose 10 hit reaction begins torso recoiling, sword lowered. Pose 11 peak hit reaction eyes shut, torso recoiling further. Pose 12 recovering from hit, feet braced, sword returning. No wounded blood, no weapon arcs/effects. Preserve all proportions and the same scale."
    },
    {
      "key": "arena-defesa",
      "prompt": "Use case: identity-preserve. New production 2D combat sprite atlas. Reference 1 is the APPROVED NEW girl's identity and detailed hand-painted storybook sprite quality. Keep her EXACT face, brown eyes, brown pigtails/pink bows, cream and pink embroidered dress, brown boots, toddler anatomy, short neck. Reference 2 is action/staging reference ONLY, NOT its low-detail pixel style or facial proportions. Same light and proportions in every cell. All full-body sprites face RIGHT, three-quarter side view. Sword is a small wooden toy sword with cream wooden blade and pale cyan crossguard. Genuine alpha-transparent background, NO brown backdrop, NO floor, NO ground shadow, NO text, NO grid, NO sparks or sword arcs. Generous transparent gaps and margins. Head size must be IDENTICAL in crouching/jumping/standing cells; change limb articulation rather than shrinking entire figure. Layout THREE columns by TWO rows, exactly six equal cells. Six gradual DEFENSE-entry poses, left to right then top to bottom: first ready neutral sword low, second arms begin raising, third sword halfway in front, fourth sword upright guarding chest, fifth full guard sword diagonal in front of chest and face clear, sixth firmly planted defensive guard. The girl grips the sword with BOTH HANDS, natural bent elbows. Small controlled movement, no walking. Same head size, same feet baseline, same body position in all six frames. Stable coherent transition, not six unrelated stances."
    }
  ]
}
